      // atan2 は +180°/-180° の境界で値が反転する。単純な差分だと指を数度
      // 動かしただけで約360°回転するため、常に最短角の増分へ正規化する。
      const angleDelta = ((next.angle - pair.angle + 540) % 360) - 180;
      Scene.setRotateDeg(pair.rotate + angleDelta);
      // 増分中心を更新しつつ、倍率・回転の基準値は現在値へ追随させる。
