      canvas.width = Math.max(1, Math.round(data.width * ratio)); canvas.height = Math.max(1, Math.round(data.height * ratio));
      const scaleX = (scene.mediaEl.naturalWidth || scene.mediaEl.width) / scene.mediaWidth;
