        const annotation = /^\/(?:api\/)?annotations(?:[/?]|$)/.test(String(path || ''));
        // 注釈の履歴・描画には保存先が返す正式なidが必要。送信待ちを保存成功へ
        // 置き換えず、失敗を描画側へ返して選択・プレビューを再試行可能に保つ。
